#pragma once
#include "Dynamics.h"
static void testDynamics(const File& root,Assets& assets){
    for(int mode=0;mode<4;++mode){DynamicsOptions d;d.mode=(DynamicsMode)mode;DynamicsOptions read;expect(dynamicsFromJson(dynamicsToJson(d),read).wasOk()&&read==d,"all dynamics modes roundtrip strict typed options");}
    for(auto field:{"range","hysteresis","hold","knee","mode"}){auto json=dynamicsToJson({});json.getDynamicObject()->removeProperty(field);DynamicsOptions d;expect(dynamicsFromJson(json,d).failed(),"incomplete modern dynamics settings reject atomically");}
    for(double rate:{8000.,44100.,48000.,96000.,192000.}){PeakDynamics limiter;DynamicsOptions d;d.mode=DynamicsMode::limiter;limiter.prepare(rate);limiter.configure(d,-12,4,.1f,120,12);float largest=0;bool stereo=true,finite=true;for(int i=0;i<30000;++i){float l=(float)(4*std::sin(i*.27)),r=l*-.25f;float gr=limiter.process(0,l,r);largest=jmax(largest,std::abs(l));stereo&=std::abs(r+l*.25f)<1.e-6f;finite&=std::isfinite(l)&&std::isfinite(gr)&&gr>=0;}expect(largest<=Decibels::decibelsToGain(-12.f)+1.e-6f&&largest>.2f&&stereo&&finite,"sample-peak limiter respects ceiling with input boost at every supported sample rate and preserves stereo ratio");}
    PeakDynamics gate;DynamicsOptions d;d.mode=DynamicsMode::gate;d.hold=10;d.hysteresis=6;d.range=60;gate.prepare(8000);gate.configure(d,-20,4,.1f,5,0);float l=0,r=0;for(int i=0;i<1000;++i){l=r=.2f;gate.process(.2f,l,r);}expect(l>.199f,"gate attack opens above threshold");for(int i=0;i<1000;++i){l=r=.2f;gate.process(.08f,l,r);}expect(l>.199f,"gate hysteresis retains an open gate below its opening threshold");for(int i=0;i<70;++i){l=r=.2f;gate.process(.02f,l,r);}expect(l>.199f,"gate hold delays closing for the selected duration");for(int i=0;i<1000;++i){l=r=.2f;gate.process(.02f,l,r);}expect(std::abs(l-.0002f)<1.e-6f,"gate release settles at the configured attenuation floor");gate.reset();l=r=.2f;gate.process(.02f,l,r);expect(l<.00021f,"reset removes gate holds and restores its closed floor");
    d.mode=DynamicsMode::expander;PeakDynamics expander;expander.prepare(48000);expander.configure(d,-20,2,.1f,5,0);float reduction=0;for(int i=0;i<3000;++i){l=r=.01f;reduction=expander.process(.01f,l,r);}expect(std::abs(l-.001f)<.000001f&&std::abs(reduction-20)<.01f,"downward 2:1 expander follows the static transfer curve below threshold");expander.configure(d,-20,1,.1f,5,0);for(int i=0;i<3000;++i){l=r=.01f;expander.process(.01f,l,r);}expect(std::abs(l-.01f)<.000001f,"expander unity ratio is transparent after its attack transition");
    auto song=emptyProject();song.songMode=false;song.loop=false;song.bpm=120;song.master=1;song.patterns[0].length=4;song.patterns[0].lanes[7]={{0,3,60,1}};song.tracks[7].send=0;song.tracks[7].volume=1.5f;auto& m=song.masterMixer;m.compressor=true;m.threshold=-24;m.dynamics.mode=DynamicsMode::limiter;auto limited=render(song,assets,root,96000,127);expect(limited.getMagnitude(0,0,96000)<=Decibels::decibelsToGain(-24.f)+1.e-6f&&limited.getMagnitude(0,0,96000)>.01f,"Master limiter caps actual summed callback audio");expect(limited==render(song,assets,root,96000,733),"limiter audio is independent of callback block size");
    RenderSettings settings;settings.bits=32;settings.tailSeconds=0;settings.endBeat=4;auto wav=root.getChildFile("master-limiter.wav");String error;expect(renderAudio(song,assets,root,wav,settings).wasOk(),"limiter exports through the shared offline engine");auto* file=assets.load(wav,error);expect(file&&file->audio==limited,"limiter callback and float export match sample for sample");
    auto dry=song;dry.masterMixer.compressor=false;auto base=render(dry,assets,root,96000);for(int mode=2;mode<=3;++mode){auto wet=dry;wet.masterMixer.compressor=true;wet.masterMixer.dynamics.mode=(DynamicsMode)mode;wet.masterMixer.threshold=0;wet.masterMixer.ratio=4;wet.masterMixer.dynamics.range=60;auto a=render(wet,assets,root,96000,127);expect(a.getRMSLevel(0,24000,24000)<base.getRMSLevel(0,24000,24000)*.1f,"gate and expander attenuate actual quiet Master audio");expect(a==render(wet,assets,root,96000,733),"gate and expander state is independent of callback size");}
    auto hard=dry;hard.masterMixer.compressor=true;hard.masterMixer.dynamics.mode=DynamicsMode::compressor;hard.masterMixer.threshold=-12;hard.masterMixer.ratio=8;auto soft=hard;soft.masterMixer.dynamics.knee=24;expect(render(hard,assets,root,48000)!=render(soft,assets,root,48000),"optional soft knee changes compressor audio while default zero retains the old curve");
    auto monitored=emptyProject();monitored.songMode=false;monitored.patterns[0].length=64;monitored.master=1;monitored.tracks[7].send=0;monitored.tracks[7].volume=1;monitored.masterMixer.compressor=true;monitored.masterMixer.threshold=-18;monitored.masterMixer.compAttack=.1f;monitored.masterMixer.compRelease=1000;monitored.masterMixer.ratio=8;auto live=makeEngine(monitored,assets,root);AudioBuffer<float> input(2,4096),output(2,4096);for(int ch=0;ch<2;++ch)for(int i=0;i<4096;++i)input.setSample(ch,i,1);for(int i=0;i<16;++i)live->render(output.getWritePointer(0),output.getWritePointer(1),4096,{input.getReadPointer(0),input.getReadPointer(1),7,1});expect(live->masterGainReduction.load()>5,"live compressor fixture establishes substantial reduction on monitored input");String liveWarnings;monitored.masterMixer.dynamics.mode=DynamicsMode::gate;compilePlayback(monitored,assets,root,live->exchange.beginWrite(),liveWarnings);live->exchange.publish();for(int i=0;i<4;++i)live->render(output.getWritePointer(0),output.getWritePointer(1),4096,{input.getReadPointer(0),input.getReadPointer(1),7,1});monitored.masterMixer.dynamics.mode=DynamicsMode::compressor;compilePlayback(monitored,assets,root,live->exchange.beginWrite(),liveWarnings);live->exchange.publish();for(int ch=0;ch<2;++ch)for(int i=0;i<4096;++i)input.setSample(ch,i,.001f);live->render(output.getWritePointer(0),output.getWritePointer(1),4096,{input.getReadPointer(0),input.getReadPointer(1),7,1});expect(live->masterGainReduction.load()==0,"returning from gate to compressor does not revive an old loud detector envelope on quiet audio");
    auto saved=root.getChildFile("extended-dynamics.pulse");Project loaded;expect(saveProject(song,saved).wasOk()&&loadProject(saved,loaded).wasOk()&&loaded.masterMixer.dynamics==song.masterMixer.dynamics,"schema 22 persists complete Master dynamics options");for(int mode=0;mode<4;++mode){auto p=song;p.tracks[7].mixer.dynamics.mode=(DynamicsMode)mode;expect(projectFromJson(projectToJson(p),loaded).wasOk()&&loaded.tracks[7].mixer.dynamics==p.tracks[7].mixer.dynamics,"all source dynamics modes roundtrip project persistence");}
    auto legacy=dry;legacy.masterMixer={};for(int schema=1;schema<=21;++schema){auto json=projectToJson(legacy);json.getDynamicObject()->setProperty("schema",schema);for(auto& t:*json["tracks"].getArray())t["mixer"].getDynamicObject()->removeProperty("dynamics");auto* chain=json["masterEffects"]["chain"].getDynamicObject();chain->setProperty("schema",1);json["masterEffects"]["chain"]["settings"].getDynamicObject()->removeProperty("dynamics");expect(projectFromJson(json,loaded).wasOk()&&loaded.masterMixer.dynamics==DynamicsOptions{}&&loaded.tracks[7].mixer.dynamics==DynamicsOptions{},"every older project schema migrates to legacy compressor mode and hard knee");}
    auto preset=captureEffectChain("Limiter",song.masterMixer);EffectChainPreset read;expect(effectChainFromJson(effectChainToJson(preset),read).wasOk()&&read.settings.dynamics==preset.settings.dynamics,"effect-chain schema 2 retains dynamics modes and controls");auto old=effectChainToJson(captureEffectChain("Legacy",Track::Mixer{}));old.getDynamicObject()->setProperty("schema",1);old["settings"].getDynamicObject()->removeProperty("dynamics");expect(effectChainFromJson(old,read).wasOk()&&read.settings.dynamics==DynamicsOptions{},"legacy effect-chain schema 1 remains readable");
    auto before=JSON::toString(projectToJson(loaded));for(int bad=0;bad<5;++bad){auto json=projectToJson(song);auto* options=json["masterEffects"]["chain"]["settings"]["dynamics"].getDynamicObject();if(bad==0)options->setProperty("range",97);if(bad==1)options->setProperty("mode",4);if(bad==2)options->removeProperty("hold");if(bad==3)json.getDynamicObject()->setProperty("schema",21);if(bad==4)json["tracks"][7]["mixer"].getDynamicObject()->removeProperty("dynamics");expect(projectFromJson(json,loaded).failed()&&JSON::toString(projectToJson(loaded))==before,"invalid or mislabeled dynamics projects reject without replacing the destination");}
    Project edited;auto edits=JSON::parse(R"([{"op":"set_song","masterEffects":{"compressor":{"mode":"limiter","threshold":-1,"release":100}}},{"op":"set_track","track":7,"effects":{"compressor":{"mode":"gate","range":72,"hysteresis":4,"hold":80,"knee":6}}}])");expect(applyControlEdits(dry,edits,edited).wasOk()&&edited.masterMixer.dynamics.mode==DynamicsMode::limiter&&edited.tracks[7].mixer.dynamics.mode==DynamicsMode::gate&&edited.tracks[7].mixer.dynamics.hold==80,"MCP authors Master limiter and channel gate together atomically");before=JSON::toString(projectToJson(edited));for(const char* bad:{R"({"mode":"unknown"})",R"({"mode":true})",R"({"range":97})",R"({"hold":1001})",R"({"knee":-1})"}){auto op=JSON::parse(R"([{"op":"set_song","title":"Must not commit"},{"op":"set_track","track":7,"effects":{"compressor":{}}}])");op[1]["effects"].getDynamicObject()->setProperty("compressor",JSON::parse(bad));expect(applyControlEdits(dry,op,edited).failed()&&JSON::toString(projectToJson(edited))==before,"invalid MCP dynamics reject the whole batch");}
    auto invalid=song;invalid.masterMixer.dynamics.hold=std::nanf("");auto bytes=saved.loadFileAsString();expect(saveProject(invalid,saved).failed()&&saved.loadFileAsString()==bytes,"nonfinite dynamics cannot overwrite a valid project");auto playback=std::make_unique<Playback>();String warnings;expect(compilePlayback(invalid,assets,root,*playback,warnings).failed(),"nonfinite dynamics cannot enter the audio callback");
}
